using System;
using System.Collections.Generic;
using System.IO;
using System.Windows.Forms;
namespace Astera {
static class LiveVideoAudit {
    internal static int Run(string root,string id,List<string> checks){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var form=new YouTubeDialog(root,id))using(var timer=new Timer{Interval=500}){form.TopMost=true;int ticks=0,code=1,playing=0;bool checking=false,requested=false;timer.Tick+=async delegate{if(checking)return;checking=true;try{if(++ticks>90)throw new IOException("YouTube player did not become ready before timeout");if(form.Initialization==null||!form.Initialization.IsCompleted)return;if(form.Browser.CoreWebView2==null)throw new IOException("WebView2 initialization failed");var core=form.Browser.CoreWebView2;string state=(await core.ExecuteScriptAsync("window.asteraState||'loading'")).Trim('"');if(state.StartsWith("error:"))throw new IOException("YouTube embed returned "+state);if(state!="ready")return;if(!requested){requested=true;await core.ExecuteScriptAsync("player.mute();player.playVideo();");return;}string position=await core.ExecuteScriptAsync("player.getCurrentTime()");double time;if(Double.TryParse(position,System.Globalization.NumberStyles.Any,System.Globalization.CultureInfo.InvariantCulture,out time)&&time>0.2)playing++;if(playing<2)return;await core.ExecuteScriptAsync("player.pauseVideo();");checks.Add("Actual WebView2 YouTube embed becomes ready and muted playback advances before pause");using(var bitmap=new System.Drawing.Bitmap(form.Width,form.Height)){using(var g=System.Drawing.Graphics.FromImage(bitmap))g.CopyFromScreen(form.PointToScreen(System.Drawing.Point.Empty),System.Drawing.Point.Empty,form.ClientSize);bitmap.Save(Path.Combine(root,"youtube-player.png"));}File.WriteAllText(Path.Combine(root,"result.json"),MC2Pack.Engine.Json.Serialize(new{Passed=true,Checks=checks,VideoId=id,MutedPlaybackVerified=true,LiveGamesChanged=false}));code=0;timer.Stop();form.Close();}catch(Exception error){File.WriteAllText(Path.Combine(root,"failure.txt"),error.ToString());timer.Stop();form.Close();}finally{checking=false;}};form.Shown+=delegate{timer.Start();};Application.Run(form);return code;}}
}
}
